// Override findPath to use g as primary sort, manhattan-to-goal as tie-breaker.
// Tie-breaking is purely for ordering — h is never added to f — so path cost
// is identical to plain Dijkstra (optimal paths guaranteed).
DijkstraFinder.prototype.findPath = function(startX, startY, endX, endY, grid) {
    var openList = new Heap(function(nodeA, nodeB) {
            var diff = nodeA.g - nodeB.g;
            if (diff !== 0) return diff;
            return nodeA.h - nodeB.h;
        }),
        startNode = grid.getNodeAt(startX, startY),
        endNode = grid.getNodeAt(endX, endY),
        diagonalMovement = this.diagonalMovement,
        abs = Math.abs, SQRT2 = Math.SQRT2,
        node, neighbors, neighbor, i, l, x, y, ng;

    startNode.g = 0;
    startNode.h = abs(startX - endX) + abs(startY - endY);
    startNode.f = 0;
    openList.push(startNode);
    startNode.opened = true;

    while (!openList.empty()) {
        node = openList.pop();
        node.closed = true;

        if (node === endNode) {
            return Util.backtrace(endNode);
        }

        neighbors = grid.getNeighbors(node, diagonalMovement);
        for (i = 0, l = neighbors.length; i < l; ++i) {
            neighbor = neighbors[i];
            if (neighbor.closed) continue;

            x = neighbor.x;
            y = neighbor.y;
            ng = node.g + ((x - node.x === 0 || y - node.y === 0) ? 1 : SQRT2);

            if (!neighbor.opened || ng < neighbor.g) {
                neighbor.g = ng;
                neighbor.h = abs(x - endX) + abs(y - endY);
                neighbor.f = neighbor.g;
                neighbor.parent = node;

                if (!neighbor.opened) {
                    openList.push(neighbor);
                    neighbor.opened = true;
                } else {
                    openList.updateItem(neighbor);
                }
            }
        }
    }

    return [];
};

module.exports = DijkstraFinder;

