var Heap = require('heap');
var Util = require('../core/Util');
var AStarFinder = require('./AStarFinder');

/**
 * Dijkstra path-finder.
 * @constructor
 * @extends AStarFinder
 * @param {Object} opt
 * @param {boolean} opt.allowDiagonal Whether diagonal movement is allowed.
 *     Deprecated, use diagonalMovement instead.
 * @param {boolean} opt.dontCrossCorners Disallow diagonal movement touching
 *     block corners. Deprecated, use diagonalMovement instead.
 * @param {DiagonalMovement} opt.diagonalMovement Allowed diagonal movement.
 */
function DijkstraFinder(opt) {
    AStarFinder.call(this, opt);
    this.heuristic = function(dx, dy) {
        return 0;
    };
}

DijkstraFinder.prototype = new AStarFinder();
DijkstraFinder.prototype.constructor = DijkstraFinder;

// Use g as primary sort key; manhattan-to-goal as tie-breaker (never added to
// path cost, so optimal paths are guaranteed). This mirrors Dijkstra semantics
// while steering expansion toward the goal when g values are equal.
DijkstraFinder.prototype.findPath = function(startX, startY, endX, endY, grid) {
    var abs = Math.abs;
    var openList = new Heap(function(nodeA, nodeB) {
            var diff = nodeA.g - nodeB.g;
            if (diff !== 0) return diff;
            return nodeA.tb - nodeB.tb;
        }),
        startNode = grid.getNodeAt(startX, startY),
        endNode = grid.getNodeAt(endX, endY),
        diagonalMovement = this.diagonalMovement,
        SQRT2 = Math.SQRT2,
        node, neighbors, neighbor, i, l, x, y, ng;
    var count = 0;

    startNode.g = 0;
    startNode.tb = abs(startX - endX) + abs(startY - endY);
    openList.push(startNode);
    startNode.opened = true;

    while (!openList.empty()) {
        node = openList.pop();
        node.closed = true;
        count++;

        if (node === endNode) {
            this._lastCount = count;
            return Util.backtrace(endNode);
        }

        neighbors = grid.getNeighbors(node, diagonalMovement);
        for (i = 0, l = neighbors.length; i < l; ++i) {
            neighbor = neighbors[i];
            if (neighbor.closed) continue;

            x = neighbor.x;
            y = neighbor.y;
            ng = node.g + ((x - node.x === 0 || y - node.y === 0) ? 1 : SQRT2);

            if (!neighbor.opened || ng < neighbor.g) {
                neighbor.g = ng;
                neighbor.tb = abs(x - endX) + abs(y - endY);
                neighbor.parent = node;

                if (!neighbor.opened) {
                    openList.push(neighbor);
                    neighbor.opened = true;
                } else {
                    openList.updateItem(neighbor);
                }
            }
        }
    }

    this._lastCount = count;
    return [];
};

