var Heap = require('heap');
var AStarFinder = require('./AStarFinder');

/**
 * Dijkstra path-finder.
 * @constructor
 * @extends AStarFinder
 * @param {Object} opt
 * @param {boolean} opt.allowDiagonal Whether diagonal movement is allowed.
 *     Deprecated, use diagonalMovement instead.
 * @param {boolean} opt.dontCrossCorners Disallow diagonal movement touching
 *     block corners. Deprecated, use diagonalMovement instead.
 * @param {DiagonalMovement} opt.diagonalMovement Allowed diagonal movement.
 */
function DijkstraFinder(opt) {
    AStarFinder.call(this, opt);
    this.heuristic = function(dx, dy) {
        return 0;
    };
}

DijkstraFinder.prototype = new AStarFinder();
DijkstraFinder.prototype.constructor = DijkstraFinder;

// Jump from (x, y) in cardinal direction (dx, dy). Returns [jx, jy] or null.
// A jump point is: the goal, or a node with a forced neighbor.
function cardinalJump(x, y, dx, dy, grid, endX, endY) {
    while (true) {
        if (!grid.isWalkableAt(x, y)) return null;
        if (x === endX && y === endY) return [x, y];
        if (dx !== 0) {
            // Horizontal: forced neighbor exists when obstacle adjacent (behind+perp)
            if ((!grid.isWalkableAt(x, y - 1) && grid.isWalkableAt(x + dx, y - 1)) ||
                (!grid.isWalkableAt(x, y + 1) && grid.isWalkableAt(x + dx, y + 1))) {
                return [x, y];
            }
        } else {
            // Vertical
            if ((!grid.isWalkableAt(x - 1, y) && grid.isWalkableAt(x - 1, y + dy)) ||
                (!grid.isWalkableAt(x + 1, y) && grid.isWalkableAt(x + 1, y + dy))) {
                return [x, y];
            }
        }
        x += dx;
        y += dy;
    }
}

// Get pruned successors for JPS (cardinal-only movement).
function identifySuccessors(node, grid, endX, endY, openList) {
    var x = node.x, y = node.y;
    var successors = [];

    // Determine movement directions based on parent
    var dirs;
    if (!node.parent) {
        dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    } else {
        var px = node.parent.x, py = node.parent.y;
        var dx = x - px, dy = y - py;
        // Normalize
        dx = dx === 0 ? 0 : (dx > 0 ? 1 : -1);
        dy = dy === 0 ? 0 : (dy > 0 ? 1 : -1);

        dirs = [];
        if (dx !== 0) {
            // Moving horizontally
            dirs.push([dx, 0]);  // continue
            if (!grid.isWalkableAt(x, y - 1)) dirs.push([0, -1]);  // forced up
            if (!grid.isWalkableAt(x, y + 1)) dirs.push([0, 1]);   // forced down
        } else {
            // Moving vertically
            dirs.push([0, dy]);  // continue
            if (!grid.isWalkableAt(x - 1, y)) dirs.push([-1, 0]);  // forced left
            if (!grid.isWalkableAt(x + 1, y)) dirs.push([1, 0]);   // forced right
        }
    }

    for (var i = 0; i < dirs.length; i++) {
        var d = dirs[i];
        var jp = cardinalJump(x + d[0], y + d[1], d[0], d[1], grid, endX, endY);
        if (!jp) continue;

        var jnode = grid.getNodeAt(jp[0], jp[1]);
        if (jnode.closed) continue;

        var ng = node.g + Math.abs(jp[0] - x) + Math.abs(jp[1] - y);
        if (!jnode.opened || ng < jnode.g) {
            jnode.g = ng;
            jnode.parent = node;
            if (!jnode.opened) {
                openList.push(jnode);
                jnode.opened = true;
            } else {
                openList.updateItem(jnode);
            }
        }
    }
}

// Reconstruct path: trace parent chain and interpolate straight-line segments.
function reconstructPath(endNode) {
    var path = [];
    var node = endNode;
    while (node) {
        var parent = node.parent;
        if (parent) {
            var dx = node.x > parent.x ? 1 : (node.x < parent.x ? -1 : 0);
            var dy = node.y > parent.y ? 1 : (node.y < parent.y ? -1 : 0);
            var cx = node.x, cy = node.y;
            while (cx !== parent.x || cy !== parent.y) {
                path.push([cx, cy]);
                cx -= dx;
                cy -= dy;
            }
        } else {
            path.push([node.x, node.y]);
        }
        node = parent;
    }
    return path.reverse();
}

// JPS-based Dijkstra: same optimal paths, far fewer nodes explored by skipping
// symmetric sub-paths in uniform-cost corridors.
DijkstraFinder.prototype.findPath = function(startX, startY, endX, endY, grid) {
    var openList = new Heap(function(a, b) { return a.g - b.g; });
    var startNode = grid.getNodeAt(startX, startY);
    var endNode = grid.getNodeAt(endX, endY);
    var count = 0;

    startNode.g = 0;
    openList.push(startNode);
    startNode.opened = true;

    while (!openList.empty()) {
        var node = openList.pop();
        node.closed = true;
        count++;

        if (node === endNode) {
            this._lastCount = count;
            return reconstructPath(endNode);
        }

        identifySuccessors(node, grid, endX, endY, openList);
    }

    this._lastCount = count;
    return [];
};

module.exports = DijkstraFinder;

