var Heap = require('heap');
var Util = require('../core/Util');
var AStarFinder = require('./AStarFinder');

/**
 * Dijkstra path-finder.
 * @constructor
 * @extends AStarFinder
 * @param {Object} opt
 * @param {boolean} opt.allowDiagonal Whether diagonal movement is allowed.
 *     Deprecated, use diagonalMovement instead.
 * @param {boolean} opt.dontCrossCorners Disallow diagonal movement touching
 *     block corners. Deprecated, use diagonalMovement instead.
 * @param {DiagonalMovement} opt.diagonalMovement Allowed diagonal movement.
 */
function DijkstraFinder(opt) {
    AStarFinder.call(this, opt);
    this.heuristic = function(dx, dy) {
        return 0;
    };
}

DijkstraFinder.prototype = new AStarFinder();
DijkstraFinder.prototype.constructor = DijkstraFinder;

// Bidirectional Dijkstra: run forward from start and backward from goal
// simultaneously; meet in the middle. Guarantees optimal paths and explores
// roughly half the nodes compared to unidirectional Dijkstra.
DijkstraFinder.prototype.findPath = function(startX, startY, endX, endY, grid) {
    var SQRT2 = Math.SQRT2;
    var diagonalMovement = this.diagonalMovement;
    var count = 0;

    // Two separate grids for forward/backward state
    var gridF = grid;
    var gridB = grid.clone();

    var startNode = gridF.getNodeAt(startX, startY);
    var endNode = gridF.getNodeAt(endX, endY);
    var startNodeB = gridB.getNodeAt(startX, startY);
    var endNodeB = gridB.getNodeAt(endX, endY);

    var BY_G = function(a, b) { return a.g - b.g; };
    var openF = new Heap(BY_G);
    var openB = new Heap(BY_G);

    startNode.g = 0;
    endNodeB.g = 0;

    openF.push(startNode);
    startNode.opened = true;

    openB.push(endNodeB);
    endNodeB.opened = true;

    var mu = Infinity;     // best path cost found so far
    var meetF = null;      // meeting node on forward grid
    var meetB = null;      // meeting node on backward grid

    // gF[x][y] = best known forward g; gB[x][y] = best known backward g
    // We store them on the node objects directly (different grid instances).

    while (!openF.empty() && !openB.empty()) {
        // Termination: if both frontiers' minimum g sums >= mu, we're done
        if (openF.peek().g + openB.peek().g >= mu) {
            break;
        }

        // Expand cheaper frontier
        if (openF.peek().g <= openB.peek().g) {
            var node = openF.pop();
            node.closed = true;
            count++;

            // Check if this node has been reached by backward search
            var nb = gridB.getNodeAt(node.x, node.y);
            if (nb.closed) {
                var candidate = node.g + nb.g;
                if (candidate < mu) {
                    mu = candidate;
                    meetF = node;
                    meetB = nb;
                }
            }

            var neighbors = gridF.getNeighbors(node, diagonalMovement);
            for (var i = 0; i < neighbors.length; i++) {
                var neighbor = neighbors[i];
                if (neighbor.closed) continue;
                var x = neighbor.x, y = neighbor.y;
                var ng = node.g + ((x - node.x === 0 || y - node.y === 0) ? 1 : SQRT2);
                if (!neighbor.opened || ng < neighbor.g) {
                    neighbor.g = ng;
                    neighbor.parent = node;
                    if (!neighbor.opened) {
                        openF.push(neighbor);
                        neighbor.opened = true;
                    } else {
                        openF.updateItem(neighbor);
                    }
                }
            }
        } else {
            var nodeB = openB.pop();
            nodeB.closed = true;
            count++;

            // Check if this node has been reached by forward search
            var nf = gridF.getNodeAt(nodeB.x, nodeB.y);
            if (nf.closed) {
                var candidate = nodeB.g + nf.g;
                if (candidate < mu) {
                    mu = candidate;
                    meetF = nf;
                    meetB = nodeB;
                }
            }

            var neighborsB = gridB.getNeighbors(nodeB, diagonalMovement);
            for (var j = 0; j < neighborsB.length; j++) {
                var nbr = neighborsB[j];
                if (nbr.closed) continue;
                var bx = nbr.x, by = nbr.y;
                var nbg = nodeB.g + ((bx - nodeB.x === 0 || by - nodeB.y === 0) ? 1 : SQRT2);
                if (!nbr.opened || nbg < nbr.g) {
                    nbr.g = nbg;
                    nbr.parent = nodeB;
                    if (!nbr.opened) {
                        openB.push(nbr);
                        nbr.opened = true;
                    } else {
                        openB.updateItem(nbr);
                    }
                }
            }
        }
    }

    this._lastCount = count;

    if (mu === Infinity) {
        return [];
    }

    // Forward path: [start, ..., meetF]
    var pathF = Util.backtrace(meetF);
    // Backward path: meetB.parent → ... → endNodeB (parent points toward goal).
    // Skip meetB to avoid duplicating the meeting coordinate.
    var pathBseg = [];
    var cur = meetB.parent;
    while (cur) {
        pathBseg.push([cur.x, cur.y]);
        cur = cur.parent;
    }
